277	/**
278	 * A declarative body-parsing route entry for {@link buildRoutes} and
279	 * {@link dispatchRoute}.
280	 *
281	 * - `method` — HTTP method (uppercase).
282	 * - `path` — Exact string path or a RegExp with named capture groups.
283	 * - `handler` — Receives the parsed body (or `undefined` when `noBody` is
284	 *   set), any named capture groups extracted from the RegExp match, and the
285	 *   parsed query parameters from the request URL.
286	 * - `statusCode` — Response status code (default `200`). Use `204` for empty
287	 *   responses — the dispatcher writes the header and skips `sendJson()`.
288	 * - `noBody` — When `true`, skip `readJsonBody()`.
289	 */
290	export interface Route {
291	  method: string;
292	  path: string | RegExp;
293	  handler: (body: unknown, groups?: Record<string, string>, query?: URLSearchParams) => Promise<unknown>;
294	  statusCode?: number;
295	  noBody?: boolean;
