302	/**
303	 * Guards against path-traversal attacks on URL parameters that are used as
304	 * filesystem path segments.
305	 *
306	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
307	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
308	 * callers receive the same status as a missing project — no information leak.
309	 *
310	 * @param segment - The raw URL parameter value to validate.
311	 */
312	function assertSafeSlug(segment: string): void {
313	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
314	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
315	  }
316	}
